"""Assemble the 180px apple-touch-icon from the seven transport-verified
base64 chunks, prove byte-fidelity via SHA-256 against the browser-side
digest, and write the file only on an exact match. One-off helper."""
import base64, hashlib, sys

BROWSER_SHA256 = "f250667bb841d19bcfbf109a0d968adc2505694b987e73abf258bf67a2d3e57a"
BROWSER_BYTES = 4005

CHUNKS = [
    "",
    "",
    "",
    "",
    "",
    "",
    "u762y46Btl3J9U6Ygda7vrbLjoG2Xcn1TpiB1ru+tsuOgbZdyfVOmIHWu762y46Btl3J9U6Ygda7vrbLjoG2Xcn1TpiB1ru+tsuOgbZdyfVOmIHWu762y46Btl3J9U74T+1MzkgwobykAAAAAElFTkSuQmCC",
]

def main():
    b64 = "".join(CHUNKS)
    assert len(b64) == 5340, f"expected 5340 base64 chars, got {len(b64)}"
    data = base64.b64decode(b64)
    sha = hashlib.sha256(data).hexdigest()
    print(f"assembled {len(data)} bytes | sha256 {sha}")
    if len(data) != BROWSER_BYTES or sha != BROWSER_SHA256:
        print("MISMATCH against browser digest — refusing to write")
        sys.exit(1)
    with open("apple-touch-icon.png", "wb") as f:
        f.write(data)
    print("apple-touch-icon.png WRITTEN — byte-identical to browser output")

if __name__ == "__main__":
    main()
